 if(a==='note')openDialog(`<h2>家族に、ひとこと。</h2><form id="noteForm"><label class="field">家族の置き手紙<textarea name="note" maxlength="2000">${esc(state().note)}</textarea></label>${formActions('メモを残す')}</form>`);
 if(a==='food')foodDialog(food(id));
 if(a==='batchHistory'){const b=batch(id);openDialog(`<h2>${esc(b.name)}</h2><p>${b.madeOn?esc(b.madeOn)+'作成':'作った日なし'} ／ 残り ${b.quantity}個</p>${state().stockEvents.filter(x=>x.batchId===id).slice().reverse().map(x=>`<div class="listItem"><div><b>${esc(x.kind)}</b><small>${dateTimeLabel(x.at)} ／ ${esc(x.actor)}</small></div><b>${x.delta>0?'+':''}${x.delta}個</b></div>`).join('')}`)}
 if(a==='export'){try{const data=await api('/api/export');const blob=new Blob([JSON.stringify(data,null,2)],{type:'application/json'}),url=URL.createObjectURL(blob),a=document.createElement('a');a.href=url;a.download='もぐ日和_バックアップ_'+jstDate()+'.json';a.click();setTimeout(()=>URL.revokeObjectURL(url),1000);showStatus('バックアップを書き出しました。保存先はブラウザのダウンロード欄で確認できます。')}catch(e){showError(e.message)}}
 if(a==='import')openDialog('<h2>バックアップから復元</h2><form id="importForm"><label class="field">もぐ日和のバックアップ<input name="backup" type="file" accept="application/json,.json" required></label><p class="hint warning">現在の内容をバックアップの内容で置き換えます。先に現在のバックアップを書き出してください。復元は取り消しボタンでは戻せません。</p><label class="checkLabel"><input type="checkbox" required><span>現在の内容を置き換えることを確認しました。</span></label>'+formActions('この内容で復元')+'</form>');
