 if(form.id==='revokeForm'){await api('/api/revoke',{method:'POST',body:'{}'});closeDialog();showStatus('他の端末の接続と未使用の招待を解除しました。');return}
 const save=(action,data,message)=>mutate(action,data,message,{form:form.id,entity:form.dataset.id||'',revision:form.dataset.revision!==undefined?Number(form.dataset.revision):current.revision});
