 if(form.id==='planForm'){const uses=Object.entries(d).filter(([k,v])=>k.startsWith('batch_')&&Number(v)>0).map(([k,v])=>({batchId:k.slice(6),quantity:Number(v)}));ok=await save('plan',{id:form.dataset.id||undefined,date:d.date,slot:d.slot,title:d.title,note:d.note,foods:splitFoods(d.foods),uses},'献立を保存しました。在庫は変えていません。');if(ok)view.selected=state().plans.find(p=>p.date===d.date&&p.slot===d.slot)?.id}
