 if(form.id==='importForm'){const file=f.get('backup');if(file.size>10000000)throw new Error('バックアップは十メガバイト以内にしてください。');const backup=JSON.parse(await file.text());if(backup.app!=='mogubiyori')throw new Error('もぐ日和のバックアップを選んでください。');ok=await save('restore',{state:backup.state},'バックアップの内容を復元しました。');}
